Lemma swrap32_land0 : forall r, -2^31 <= r < 2^31 -> bv_swrap 32 (Z.land r 18446744073709551615 + 0) = r.
Proof.
  intros r Hr. change 18446744073709551615 with (Z.ones 64). rewrite Z.land_ones by lia. rewrite Z.add_0_r.
  unfold bv_swrap, bv_wrap, bv_half_modulus, bv_modulus.
  change (2 ^ Z.of_N 32) with 4294967296. change (4294967296 `div` 2) with 2147483648. change (2 ^ 64) with 18446744073709551616.
  destruct (Z.lt_ge_cases r 0).
  - rewrite <- (Z.mod_add r 1) by lia. rewrite (Z.mod_small (r + 1 * 18446744073709551616)) by lia.
    replace (r + 1 * 18446744073709551616 + 2147483648) with ((r + 2147483648) + 4294967296 * 4294967296) by lia.
    rewrite Z.mod_add by lia. rewrite Z.mod_small by lia. lia.
  - rewrite (Z.mod_small r) by lia. rewrite Z.mod_small by lia. lia.
Qed.
