Lemma swrap32_range : forall z, -2^31 <= bv_swrap 32 z < 2^31.
Proof.
  intros z. unfold bv_swrap, bv_wrap, bv_half_modulus, bv_modulus.
  change (2 ^ Z.of_N 32) with (2 ^ 32). change (2 ^ 32 `div` 2) with (2 ^ 31).
