  rewrite Z.ldiff_land, Z.land_comm, Z.land_ones by lia. unfold Z.lnot.
  rewrite <- (Z.mod_add _ 1) by lia. change (Z.ones 64) with (2^64 - 1). rewrite Z.mod_small; lia.
